    lines = [HEADER] + [",".join(f'"{c}"' if "," in c or c.startswith("+") else c for c in row) for row in ROWS]
    # simpler: quote all text fields
    def q(v: str) -> str:
        if any(ch in v for ch in [",", '"', "\n"]):
            return '"' + v.replace('"', '""') + '"'
        return v

    body = [HEADER]
    for row in ROWS:
        body.append(",".join(q(x) for x in row))
    out.write_text("\n".join(body) + "\n", encoding="utf-8")
    print(f"Wrote {len(ROWS)} facilities to {out}")
